32: // R-01 through R-06. This regression uses the existing authenticated test
33: // server fixture and the real HTTP router, with process-separated storage.
34: func TestChatReadIntegrityAcrossProcesses(t *testing.T) {
35: 	if phase := os.Getenv(chatReadStageEnv); phase != "" {
36: 		runChatReadPhase(t, phase)
37: 		if !t.Failed() {
38: 			fmt.Println("CHAT_READ_PHASE=" + phase)
39: 		}
40: 		return
41: 	}
42: 	executable, err := os.Executable()
43: 	if err != nil {
44: 		t.Fatal(err)
45: 	}
46: 	home := t.TempDir()
47: 	for _, phase := range []string{"seed", "fault", "recover", "positive"} {
48: 		t.Run(phase, func(t *testing.T) {
49: 			ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
50: 			defer cancel()
51: 			cmd := exec.CommandContext(ctx, executable, "-test.run=^TestChatReadIntegrityAcrossProcesses$", "-test.v", "-test.timeout=25s")
52: 			cmd.Env = chatReadEnvironment(home, phase)
53: 			output, err := cmd.CombinedOutput()
54: 			t.Logf("phase=%s\n%s", phase, output)
55: 			if err != nil {
56: 				t.Fatalf("phase %s failed: %v", phase, err)
57: 			}
58: 			if !strings.Contains(string(output), "CHAT_READ_PHASE="+phase) {
59: 				t.Fatalf("phase %s did not execute its completion assertion", phase)
60: 			}
61: 		})
62: 	}
63: }
